/* Token Radar — one static page, no network, no external font.
   Dark neutral shell; the table and the detail panel carry the weight, so everything else stays quiet.
   Line-height never drops below 1.5 in prose and 1.35 in table cells: this is read, not skimmed. */

:root {
  --bg: #0d0f13;
  --panel: #14171d;
  --panel-2: #191d25;
  --line: #262c37;
  --line-soft: #1e232c;
  --ink: #e7eaf0;
  --ink-2: #b3bbc9;
  --muted: #8b94a4;
  --accent: #8fb8ff;
  --accent-dim: #38507a;
  --up: #6fd08c;
  --down: #e2868a;
  --warn: #e2c37a;
  --radius: 10px;
  --sans: ui-sans-serif, system-ui, -apple-system, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif;
  --mono: ui-monospace, SFMono-Regular, 'SF Mono', Menlo, Consolas, 'Liberation Mono', monospace;
}

* { box-sizing: border-box; }

html { background: var(--bg); }

body {
  margin: 0;
  padding: 22px clamp(14px, 3vw, 34px) 56px;
  background: var(--bg);
  color: var(--ink);
  font: 400 15px/1.6 var(--sans);
  -webkit-font-smoothing: antialiased;
}

h1, h2, h3 { margin: 0; font-weight: 600; letter-spacing: -0.01em; }

b { font-weight: 600; color: #fff; }

.sr {
  position: absolute; width: 1px; height: 1px; overflow: hidden;
  clip-path: inset(50%); white-space: nowrap;
}

.skip {
  position: absolute; left: -9999px; top: 0; padding: 10px 14px;
  background: var(--panel-2); color: var(--accent); border-radius: var(--radius);
}
.skip:focus { left: 14px; z-index: 20; }

:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
  border-radius: 4px;
}

/* ---------------------------------------------------------------- header */

.head { max-width: 1640px; margin: 0 auto 16px; }

.head-top {
  display: flex; flex-wrap: wrap; gap: 18px 32px;
  align-items: flex-start; justify-content: space-between;
}

h1 { font-size: 27px; line-height: 1.15; }

.sub {
  margin: 5px 0 0;
  color: var(--ink-2); font-size: 14px; line-height: 1.5; max-width: 60ch;
}

.stamp {
  display: flex; flex-wrap: wrap; gap: 0 26px; margin: 2px 0 0;
  padding: 9px 15px; background: var(--panel); border: 1px solid var(--line);
  border-radius: var(--radius);
}
.stamp div { display: flex; flex-direction: column; }
.stamp dt {
  color: var(--muted); font-size: 10.5px; text-transform: uppercase;
  letter-spacing: 0.09em; line-height: 1.6;
}
.stamp dd {
  margin: 0; font: 600 13.5px/1.4 var(--mono); color: var(--ink);
  font-variant-numeric: tabular-nums;
}

.lede {
  margin: 16px 0 0; max-width: 118ch;
  color: var(--ink-2); font-size: 13.5px; line-height: 1.68;
}
.lede b { color: var(--ink); }

.strip {
  display: flex; flex-wrap: wrap; gap: 7px; margin: 13px 0 0;
}
.chip {
  padding: 4px 10px; border: 1px solid var(--line-soft); border-radius: 999px;
  background: var(--panel); color: var(--ink-2);
  font: 500 11.5px/1.7 var(--mono); white-space: nowrap;
}
.chip i { color: var(--muted); font-style: normal; margin-right: 5px; }

.table-note { margin: 12px 0 0; max-width: 118ch; }
.table-note summary {
  cursor: pointer; color: var(--accent); font-size: 12.5px; line-height: 1.7;
  padding: 3px 0; width: max-content;
}
.table-note summary:hover { color: #b7d1ff; }
.note-grid {
  display: grid; grid-template-columns: repeat(auto-fit, minmax(290px, 1fr));
  gap: 4px 26px; margin-top: 8px; padding: 13px 16px;
  background: var(--panel); border: 1px solid var(--line); border-radius: var(--radius);
}
.note-grid p { margin: 0 0 7px; color: var(--ink-2); font-size: 12.5px; line-height: 1.62; }
.note-grid b { color: var(--accent); }

/* ---------------------------------------------------------------- controls */

.controls {
  display: flex; flex-wrap: wrap; gap: 10px 12px; align-items: flex-end;
  max-width: 1640px; margin: 0 auto 14px; padding: 12px 14px;
  background: var(--panel); border: 1px solid var(--line); border-radius: var(--radius);
}

.field { display: flex; flex-direction: column; gap: 4px; min-width: 0; }
.field.grow { flex: 1 1 260px; }
.field > span {
  color: var(--muted); font-size: 10.5px; text-transform: uppercase;
  letter-spacing: 0.09em; line-height: 1.5;
}

input[type='search'], select {
  height: 34px; padding: 0 10px;
  background: var(--panel-2); color: var(--ink);
  border: 1px solid var(--line); border-radius: 7px;
  font: 400 13.5px/1.4 var(--sans);
}
select { min-width: 148px; cursor: pointer; }
input[type='search']::placeholder { color: #6f7889; }
input[type='search']:hover, select:hover { border-color: #343c4a; }

.field.check {
  flex-direction: row; align-items: center; gap: 8px;
  height: 34px; padding: 0 4px; cursor: pointer;
}
.field.check span {
  text-transform: none; letter-spacing: 0; font-size: 13px; color: var(--ink-2);
}
input[type='checkbox'] {
  width: 15px; height: 15px; accent-color: var(--accent); cursor: pointer;
}

.reset {
  height: 34px; padding: 0 14px; margin-left: auto;
  background: transparent; color: var(--ink-2);
  border: 1px solid var(--line); border-radius: 7px;
  font: 500 13px/1 var(--sans); cursor: pointer;
}
.reset:hover { border-color: var(--accent-dim); color: var(--ink); }

/* ---------------------------------------------------------------- layout */

.body {
  display: grid; grid-template-columns: minmax(0, 1fr) 396px;
  gap: 16px; align-items: start;
  max-width: 1640px; margin: 0 auto;
}

.board { min-width: 0; }

.count {
  margin: 0 0 8px; color: var(--muted);
  font: 500 12px/1.6 var(--mono); font-variant-numeric: tabular-nums;
}
.count b { color: var(--ink); }

.scroll {
  border: 1px solid var(--line); border-radius: var(--radius);
  background: var(--panel); overflow: auto;
  max-height: calc(100vh - 250px);
}

table { width: 100%; border-collapse: collapse; }

thead th {
  position: sticky; top: 0; z-index: 2;
  background: var(--panel-2);
  border-bottom: 1px solid var(--line);
  padding: 0; text-align: left; white-space: nowrap;
}
thead th button {
  width: 100%; padding: 9px 11px;
  background: none; border: 0; cursor: pointer;
  color: var(--muted); font: 600 11px/1.5 var(--sans);
  text-transform: uppercase; letter-spacing: 0.07em; text-align: inherit;
}
thead th.num button, th.num { text-align: right; }
thead th button:hover { color: var(--ink); }
thead th[aria-sort] button { color: var(--accent); }
thead th[aria-sort='ascending'] button::after { content: ' ↑'; }
thead th[aria-sort='descending'] button::after { content: ' ↓'; }

tbody tr {
  border-bottom: 1px solid var(--line-soft);
  cursor: pointer;
}
tbody tr:last-child { border-bottom: 0; }
tbody tr:hover { background: #1a1f28; }
tbody tr.selected { background: #1d2532; box-shadow: inset 2px 0 0 var(--accent); }

tbody td {
  padding: 8px 11px; vertical-align: middle;
  font-size: 13px; line-height: 1.4;
}
tfoot td {
  padding: 9px 11px; color: var(--muted);
  font-size: 11.5px; line-height: 1.5;
  background: var(--panel-2); border-top: 1px solid var(--line);
}

td.num, th.num { text-align: right; }
td.num { font-family: var(--mono); font-variant-numeric: tabular-nums; }

.rank { color: var(--muted); font-variant-numeric: tabular-nums; }

.who { display: flex; flex-direction: column; gap: 1px; min-width: 0; }
.who .n { color: var(--ink); font-weight: 500; }
.who .s { color: #6f7889; font: 400 11px/1.4 var(--mono); }

.star { color: var(--warn); margin-left: 6px; font-size: 11px; }

.cat { color: var(--ink-2); }
.chains { color: var(--ink-2); font-size: 12.5px; }
.chains span { color: #6f7889; }

.up { color: var(--up); }
.down { color: var(--down); }
.flat { color: var(--muted); }

.value { color: #fff; font-weight: 600; }

.score {
  display: inline-flex; align-items: center; gap: 7px;
  justify-content: flex-end;
}
.score .bar {
  display: block; width: 34px; height: 4px; border-radius: 2px;
  background: var(--line); overflow: hidden;
}
.score .bar i { display: block; height: 100%; background: var(--accent); }

.empty {
  margin: 14px 0 0; padding: 16px; color: var(--ink-2);
  background: var(--panel); border: 1px dashed var(--line); border-radius: var(--radius);
  font-size: 13.5px; line-height: 1.6;
}

.keys {
  margin: 9px 0 0; color: #6f7889; font-size: 11.5px; line-height: 1.9;
}
kbd {
  padding: 1px 5px; border: 1px solid var(--line); border-bottom-width: 2px;
  border-radius: 4px; background: var(--panel-2); color: var(--ink-2);
  font: 500 10.5px/1.6 var(--mono);
}

/* ---------------------------------------------------------------- detail */

.detail {
  position: sticky; top: 16px;
  max-height: calc(100vh - 32px); overflow: auto;
  padding: 16px 18px 20px;
  background: var(--panel); border: 1px solid var(--line);
  border-radius: var(--radius);
}
.detail .hint {
  margin: 0; color: var(--muted); font-size: 13px; line-height: 1.7;
}

.d-head { border-bottom: 1px solid var(--line-soft); padding-bottom: 11px; margin-bottom: 13px; }
.d-rank {
  color: var(--muted); font: 600 11px/1.6 var(--mono);
  text-transform: uppercase; letter-spacing: 0.09em;
}
.d-name { font-size: 19px; line-height: 1.25; margin-top: 3px; }
.d-meta { margin: 5px 0 0; color: var(--ink-2); font-size: 12.5px; line-height: 1.6; }
.d-meta .dot { color: #4a5261; margin: 0 6px; }
.badge {
  display: inline-block; margin-top: 8px; padding: 2px 8px;
  border: 1px solid var(--accent-dim); border-radius: 999px;
  color: var(--accent); font: 500 11px/1.7 var(--mono);
}

.d-stats {
  display: grid; grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 9px 10px; margin: 0 0 15px;
}
.d-stats div {
  padding: 7px 9px; background: var(--panel-2);
  border: 1px solid var(--line-soft); border-radius: 8px;
}
.d-stats dt {
  color: var(--muted); font-size: 10px; text-transform: uppercase;
  letter-spacing: 0.08em; line-height: 1.7;
}
.d-stats dd {
  margin: 0; font: 600 13px/1.4 var(--mono);
  font-variant-numeric: tabular-nums; color: var(--ink);
}

.d-sec { margin: 0 0 16px; }
.d-sec > h3 {
  display: flex; align-items: baseline; gap: 8px;
  margin: 0 0 7px; color: var(--muted);
  font: 600 10.5px/1.6 var(--sans);
  text-transform: uppercase; letter-spacing: 0.1em;
}
.d-sec > h3 em { color: #5c6575; font-style: normal; letter-spacing: 0; text-transform: none; }
.d-sec > p { margin: 0 0 8px; color: var(--ink-2); font-size: 12.5px; line-height: 1.65; }

.ladder { width: 100%; border-collapse: collapse; }
.ladder th {
  padding: 3px 0 4px; color: #5c6575;
  font: 600 10px/1.6 var(--sans); text-transform: uppercase; letter-spacing: 0.08em;
  text-align: left; border-bottom: 1px solid var(--line-soft);
}
.ladder th.num, .ladder td.num { text-align: right; }
.ladder td {
  padding: 5px 0; border-bottom: 1px solid var(--line-soft);
  font-size: 12.5px; line-height: 1.5; vertical-align: top;
}
.ladder td.num { font-family: var(--mono); font-variant-numeric: tabular-nums; }
.ladder tr:last-child td { border-bottom: 0; padding-top: 7px; }
.ladder .factor { color: var(--ink); }
.ladder .why { color: var(--muted); font-size: 11.5px; line-height: 1.5; padding-left: 10px; }
.ladder .total { color: #fff; font-weight: 600; }
.ladder .plus { color: var(--up); }
.ladder .minus { color: var(--down); }

.steps { margin: 0; padding: 0; list-style: none; counter-reset: step; }
.steps li {
  counter-increment: step; position: relative;
  padding: 0 0 11px 27px; color: var(--ink-2);
  font-size: 12.5px; line-height: 1.62;
}
.steps li:last-child { padding-bottom: 0; }
.steps li::before {
  content: counter(step); position: absolute; left: 0; top: 1px;
  width: 18px; height: 18px; border-radius: 50%;
  background: var(--panel-2); border: 1px solid var(--accent-dim);
  color: var(--accent); font: 600 10.5px/18px var(--mono);
  text-align: center;
}
.steps li b { color: var(--ink); }

.d-foot {
  margin: 14px 0 0; padding-top: 11px; border-top: 1px solid var(--line-soft);
  color: #5c6575; font-size: 11px; line-height: 1.7;
}

/* ---------------------------------------------------------------- narrow */

@media (max-width: 1180px) {
  .body { grid-template-columns: minmax(0, 1fr); }
  .detail { position: static; max-height: none; order: -1; }
  .detail .hint { display: none; }
  .detail[data-empty='1'] { display: none; }
  .scroll { max-height: none; }
  .reset { margin-left: 0; }
}

@media (max-width: 720px) {
  body { padding: 16px 12px 40px; font-size: 14.5px; }
  h1 { font-size: 23px; }
  .stamp { gap: 0 18px; padding: 8px 12px; }
  .d-stats { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  th.chains-col, td.chains-col { display: none; }
  select { min-width: 0; width: 100%; }
  .field { flex: 1 1 140px; }
  .field.grow { flex: 1 1 100%; }
}

@media (prefers-reduced-motion: no-preference) {
  tbody tr { transition: background 90ms ease; }
}

@media print {
  body { background: #fff; color: #111; }
  .controls, .keys, .table-note, .skip { display: none; }
}
